it("invalidates a callback a port retained after schedule threw", () => {
  let ran = 0;
  let retained: (() => void) | undefined;
  const guarded = deferredScheduler({
    schedule(job: () => void): Cancel {
      retained = job;
      throw new Error("port refused after taking the job");
